@CrossOrigin
@RestController
@RequestMapping("/DataSetQuery")
public class DataSetQueryRestController extends BaseSpringRestController {
	
	public DataSetQueryRestController( DataSetService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a DataSet using a UUID
     * @param		UUID dataSetId
     * @return		DataSet
     */    
    @GetMapping("/load")
    public DataSet load( @RequestParam(required=true) UUID dataSetId ) {
    	DataSet entity = null;

    	try {  
    		entity = service.getDataSet( new DataSetFetchOneSummary( dataSetId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load DataSet using Id " + dataSetId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all DataSet business objects
     * @return		Set<DataSet>
     */
    @GetMapping("/")
    public List<DataSet> loadAll() {                
    	List<DataSet> dataSetList = null;
        
    	try {
            // load the DataSet
            dataSetList = service.getAllDataSet();
            
            if ( dataSetList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all DataSets" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all DataSets ", exc );
        	return null;
        }

        return dataSetList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected DataSet dataSet = null;
    protected DataSetService service = null;
    private static final Logger LOGGER = Logger.getLogger(DataSetQueryRestController.class.getName());
    
}
